schemaSql:
-- SQL Schema Setup for DMC (Diala Medical & Chemical Equipment) App Pair

-- 1. SETTINGS TABLE (Admin managed exchange rate and app metadata)
create table if not exists public.tarag3_settings (
    id bigint primary key generated always as identity,
    usd_rate numeric(12,2) not null default 1100.00,
    store_name text not null default 'DMC Diala Medical & Chemical Equipment',
    store_phone text not null default '0912345678',
    whatsapp_number text not null default '249912345678',
    updated_at timestamptz default now()
);

-- Ensure columns exist if table was previously created without them
alter table public.tarag3_settings add column if not exists usd_rate numeric(12,2) not null default 1100.00;
alter table public.tarag3_settings add column if not exists store_name text not null default 'DMC Diala Medical & Chemical Equipment';
alter table public.tarag3_settings add column if not exists store_phone text not null default '0912345678';
alter table public.tarag3_settings add column if not exists whatsapp_number text not null default '249912345678';
alter table public.tarag3_settings add column if not exists updated_at timestamptz default now();

alter table public.tarag3_settings enable row level security;

drop policy if exists "Authenticated users can read settings" on public.tarag3_settings;
create policy "Authenticated users can read settings" on public.tarag3_settings
    for select to authenticated
    using (true);

drop policy if exists "Admins can update settings" on public.tarag3_settings;
create policy "Admins can update settings" on public.tarag3_settings
    for all to authenticated
    using (public.tarag3_is_admin())
    with check (public.tarag3_is_admin());


-- 2. DELIVERY AREAS TABLE (Admin managed shipping regions)
create table if not exists public.tarag3_delivery_areas (
    id bigint primary key generated always as identity,
    name text not null unique,
    delivery_fee numeric(12,2) not null default 0.00,
    is_active boolean not null default true,
    created_at timestamptz default now()
);

alter table public.tarag3_delivery_areas enable row level security;

drop policy if exists "Authenticated users can view active delivery areas" on public.tarag3_delivery_areas;
create policy "Authenticated users can view active delivery areas" on public.tarag3_delivery_areas
    for select to authenticated
    using (true);

drop policy if exists "Admins can manage delivery areas" on public.tarag3_delivery_areas;
create policy "Admins can manage delivery areas" on public.tarag3_delivery_areas
    for all to authenticated
    using (public.tarag3_is_admin())
    with check (public.tarag3_is_admin());


-- 3. PRODUCTS TABLE (Catalog managed by Admin, viewed by Customers)
create table if not exists public.tarag3_products (
    id uuid primary key default gen_random_uuid(),
    name text not null,
    category text not null check (category in ('معدات', 'مستهلكات', 'مختبر')),
    description text,
    price_usd numeric(12,2) not null default 0.00,
    stock_quantity integer not null default 0,
    image_url text,
    is_visible boolean not null default true,
    created_at timestamptz default now(),
    updated_at timestamptz default now()
);

alter table public.tarag3_products enable row level security;

drop policy if exists "Authenticated users can view visible products" on public.tarag3_products;
create policy "Authenticated users can view visible products" on public.tarag3_products
    for select to authenticated
    using (is_visible = true or public.tarag3_is_admin());

drop policy if exists "Admins can manage products" on public.tarag3_products;
create policy "Admins can manage products" on public.tarag3_products
    for all to authenticated
    using (public.tarag3_is_admin())
    with check (public.tarag3_is_admin());


-- 4. ORDERS TABLE (Customer purchase requests)
create table if not exists public.tarag3_orders (
    id uuid primary key default gen_random_uuid(),
    order_number text not null unique,
    customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
    customer_name text not null,
    customer_phone text not null,
    delivery_area_id bigint references public.tarag3_delivery_areas(id) on delete set null,
    delivery_area_name text not null,
    delivery_fee numeric(12,2) not null default 0.00,
    detailed_address text,
    delivery_type text not null check (delivery_type in ('توصيل للموقع', 'استلام من المحل')),
    payment_method text not null default 'كاش عند الاستلام',
    status text not null default 'جديد' check (status in ('جديد', 'قيد التجهيز', 'في الطريق', 'تم')),
    subtotal_sdg numeric(12,2) not null default 0.00,
    total_sdg numeric(12,2) not null default 0.00,
    created_at timestamptz default now()
);

alter table public.tarag3_orders enable row level security;

drop policy if exists "Customers can read their own orders" on public.tarag3_orders;
create policy "Customers can read their own orders" on public.tarag3_orders
    for select to authenticated
    using (customer_id = auth.uid());

drop policy if exists "Customers can insert their own orders" on public.tarag3_orders;
create policy "Customers can insert their own orders" on public.tarag3_orders
    for insert to authenticated
    with check (customer_id = auth.uid());

drop policy if exists "Customers can update their own non-completed orders" on public.tarag3_orders;
create policy "Customers can update their own non-completed orders" on public.tarag3_orders
    for update to authenticated
    using (customer_id = auth.uid())
    with check (customer_id = auth.uid());

drop policy if exists "Admins have full control on orders" on public.tarag3_orders;
create policy "Admins have full control on orders" on public.tarag3_orders
    for all to authenticated
    using (public.tarag3_is_admin())
    with check (public.tarag3_is_admin());


-- 5. ORDER ITEMS TABLE (Line items per order)
create table if not exists public.tarag3_order_items (
    id uuid primary key default gen_random_uuid(),
    order_id uuid not null references public.tarag3_orders(id) on delete cascade,
    product_id uuid references public.tarag3_products(id) on delete set null,
    product_name text not null,
    quantity integer not null check (quantity > 0),
    unit_price_sdg numeric(12,2) not null,
    total_price_sdg numeric(12,2) not null,
    created_at timestamptz default now()
);

alter table public.tarag3_order_items enable row level security;

drop policy if exists "Customers can view their order items" on public.tarag3_order_items;
create policy "Customers can view their order items" on public.tarag3_order_items
    for select to authenticated
    using (
        exists (
            select 1 from public.tarag3_orders o
            where o.id = order_id and o.customer_id = auth.uid()
        )
    );

drop policy if exists "Customers can insert order items for their own orders" on public.tarag3_order_items;
create policy "Customers can insert order items for their own orders" on public.tarag3_order_items
    for insert to authenticated
    with check (
        exists (
            select 1 from public.tarag3_orders o
            where o.id = order_id and o.customer_id = auth.uid()
        )
    );

drop policy if exists "Admins have full control on order items" on public.tarag3_order_items;
create policy "Admins have full control on order items" on public.tarag3_order_items
    for all to authenticated
    using (public.tarag3_is_admin())
    with check (public.tarag3_is_admin());


-- 6. PURCHASES TABLE (Supplier purchases tracking)
create table if not exists public.tarag3_purchases (
    id uuid primary key default gen_random_uuid(),
    supplier_name text not null,
    invoice_date date not null default current_date,
    amount_sdg numeric(12,2) not null default 0.00,
    payment_status text not null check (payment_status in ('مدفوع', 'آجل')),
    notes_or_details text,
    invoice_image_url text,
    created_at timestamptz default now()
);

-- Ensure columns exist if table was previously created without them
alter table public.tarag3_purchases add column if not exists supplier_name text;
alter table public.tarag3_purchases add column if not exists invoice_date date not null default current_date;
alter table public.tarag3_purchases add column if not exists amount_sdg numeric(12,2) not null default 0.00;
alter table public.tarag3_purchases add column if not exists payment_status text;
alter table public.tarag3_purchases add column if not exists notes_or_details text;
alter table public.tarag3_purchases add column if not exists invoice_image_url text;
alter table public.tarag3_purchases add column if not exists created_at timestamptz default now();

alter table public.tarag3_purchases enable row level security;

drop policy if exists "Admins have full access to purchases" on public.tarag3_purchases;
create policy "Admins have full access to purchases" on public.tarag3_purchases
    for all to authenticated
    using (public.tarag3_is_admin())
    with check (public.tarag3_is_admin());


-- 7. PROMOTIONS LOG TABLE (Broadcast notification records)
create table if not exists public.tarag3_promotions (
    id uuid primary key default gen_random_uuid(),
    title text not null,
    body text not null,
    target_count integer default 0,
    created_at timestamptz default now()
);

alter table public.tarag3_promotions enable row level security;

drop policy if exists "Authenticated users can view promotions" on public.tarag3_promotions;
create policy "Authenticated users can view promotions" on public.tarag3_promotions
    for select to authenticated
    using (true);

drop policy if exists "Admins can insert and manage promotions" on public.tarag3_promotions;
create policy "Admins can insert and manage promotions" on public.tarag3_promotions
    for all to authenticated
    using (public.tarag3_is_admin())
    with check (public.tarag3_is_admin());


